mapper.select:
SELECT o.id AS order_id, o.product_id, p.name AS product_name, p.category, o.type, o.order_method, o.price, o.quantity, o.remaining_quantity, o.status, o.created_at, o.updated_at FROM orders o JOIN products p ON o.product_id = p.id WHERE o.member_id = #{memberId}
AND o.type = #{type}
AND o.status = #{status}
ORDER BY o.created_at DESC, o.id DESC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
FROM orders o
WHERE o.member_id = #{memberId}

    AND o.type = #{type}


    AND o.status = #{status}
